  font-weight: 500;
  color: var(--bl-ink);
  background-color: var(--bl-surface-sunken);
  border: 1px solid var(--bl-line);
  border-radius: var(--bl-radius-sm);
  box-shadow: none;
}

.sl-steps > li::after {
  background-color: var(--bl-line);
}

.sl-steps > li:last-child::after {
  display: none;
}

.sl-steps > li:last-child > :last-child {
  margin-bottom: 0;
}

---
// One screen of the app, captured in both looks; the page's theme shows the matching one.
// `name` is a capture's file name without its look: `05-clip-picture.inspector` reads
// src/assets/screens/05-clip-picture.inspector.{light,dark}.webp. An unknown name fails the build.
// A capture is at 2× and never shows larger than its real size, so a sheet looks like a sheet.
// `frame` is for a full-window capture (a `*.window` screen): it draws the capture in a window
// frame, a title bar with the site's title over it, at the full width of its container.
import { Image } from 'astro:assets';
import type { ImageMetadata } from 'astro';

interface Props {
  name: string;
  alt: string;
  caption?: string;
  frame?: boolean;
}

const { name, alt, caption, frame = false } = Astro.props;
const { siteTitle } = Astro.locals.starlightRoute;

const screens = import.meta.glob<{ default: ImageMetadata }>('../assets/screens/*.webp', {
  eager: true,
});

function shot(look: 'light' | 'dark') {
  const found = screens[`../assets/screens/${name}.${look}.webp`];
  if (!found) throw new Error(`Shot: no ${look} capture named "${name}" in src/assets/screens/`);
  return found.default;
}

const light = shot('light');
const dark = shot('dark');
---

<figure
  class:list={['fj-shot', { 'fj-shot--framed': frame }]}
  style={frame ? undefined : `max-width: ${Math.round(light.width / 2)}px`}
>
  {frame ? (
    <div class="fj-window">
      <div class="fj-window-bar" aria-hidden="true">
        <span class="fj-window-dot" />
        <span class="fj-window-dot" />
        <span class="fj-window-dot" />
        <span class="fj-window-title">{siteTitle}</span>
      </div>
      <Image class="fj-light" src={light} alt={alt} />
      <Image class="fj-dark" src={dark} alt={alt} />
    </div>
  ) : (
    <>
      <Image class="fj-light" src={light} alt={alt} />
      <Image class="fj-dark" src={dark} alt={alt} />
    </>
  )}
  {caption && <figcaption>{caption}</figcaption>}
</figure>

